import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    # Clean Price: remove $ and commas, convert to numeric
    if 'Price' in df.columns:
        df['Price'] = df['Price'].astype(str).str.replace(r'[\$,]', '', regex=True).str.strip()
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    # Clean Quantity: numeric and filter invalid (<1)
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
        df = df[df['Quantity'] >= 1]
        df = df[df['Quantity'].notna()]
    # Clean Region: normalize case variants and typos
    if 'Region' in df.columns:
        allowed = ['North', 'South', 'East', 'West']
        mapping = {'west': 'West', 'wst': 'West', 'south': 'South', 'suoth': 'South', 'north': 'North', 'east': 'East'}
        def norm_region(x):
            if pd.isna(x):
                return np.nan
            s = str(x).strip()
            if s == '' or s.lower() == 'nan':
                return np.nan
            low = s.lower()
            if low in mapping:
                return mapping[low]
            for a in allowed:
                if low == a.lower():
                    return a
            return s
        df['Region'] = df['Region'].apply(norm_region)
        # set any remaining non-allowed to NaN
        df.loc[~df['Region'].isin(allowed) & df['Region'].notna(), 'Region'] = np.nan
    # Clean Revenue formula if needed (recompute)
    if 'Revenue' in df.columns and 'Quantity' in df.columns and 'Price' in df.columns:
        df['Revenue'] = pd.to_numeric(df['Revenue'], errors='coerce')
        # recompute where mismatch to enforce formula (optional)
        # df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    # ensure cleaned (idempotent)
    # if Region still has variants, clean again
    # work on copy
    d = df.copy()
    # drop missing Region keys as required
    d = d.dropna(subset=['Region'])
    d = d[d['Region'].astype(str).str.strip() != '']
    if d.empty:
        return {}
    # ensure Quantity numeric
    d['Quantity'] = pd.to_numeric(d['Quantity'], errors='coerce')
    grouped = d.groupby('Region')['Quantity'].sum()
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # convert to int if whole number
        if pd.isna(v):
            continue
        val = int(v) if float(v).is_integer() else float(v)
        result[str(k)] = val
    return result
